 308| // CloseProviderTransformer is a GraphTransformer that adds nodes to the
 309| // graph that will close open provider connections that aren't needed anymore.
 310| // A provider connection is not needed anymore once all depended resources
 311| // in the graph are evaluated.
 312| type CloseProviderTransformer struct{}
 313| 
 314| func (t *CloseProviderTransformer) Transform(g *Graph) error {
 315| 	pm := providerVertexMap(g)
 316| 	cpm := make(map[string]*graphNodeCloseProvider)
 317| 	var err error
 318| 
 319| 	for _, p := range pm {
 320| 		key := p.ProviderAddr().String()
 321| 
 322| 		// make sure we haven't created the closer node already
 323| 		_, ok := cpm[key]
 324| 		if ok {
 325| 			log.Printf("[ERROR] CloseProviderTransformer: already created close node for %s", key)
 326| 			continue
 327| 		}
 328| 
 329| 		// create a closer for this provider type
 330| 		closer := &graphNodeCloseProvider{Addr: p.ProviderAddr()}
 331| 		g.Add(closer)
 332| 		cpm[key] = closer
 333| 
 334| 		// Close node depends on the provider itself
 335| 		// this is added unconditionally, so it will connect to all instances
 336| 		// of the provider. Extra edges will be removed by transitive
 337| 		// reduction.
 338| 		g.Connect(dag.BasicEdge(closer, p))
 339| 	}
 340| 
 341| 	// Now look for all provider consumers and connect them to the appropriate closers.
 342| 	for _, v := range g.Vertices() {
 343| 		var refs []ProviderRef
 344| 
 345| 		if pc, ok := v.(GraphNodeProviderConsumer); ok {
 346| 			refs = append(refs, pc.Provider())
 347| 		}
 348| 
 349| 		if pc, ok := v.(GraphNodeActionProviderConsumer); ok {
 350| 			refs = append(refs, pc.ActionProviders()...)
 351| 		}
 352| 
 353| 		for _, ref := range refs {
 354| 			if ref.Offline {
 355| 				// this node does not require a provider
 356| 				continue
 357| 			}
 358| 
 359| 			closer, ok := cpm[ref.String()]
 360| 			if !ok {
 361| 				return fmt.Errorf("no graphNodeCloseProvider for %s", ref)
 362| 			}
 363| 			g.Connect(dag.BasicEdge(closer, v))
 364| 		}
 365| 	}
 366| 
 367| 	return err
 368| }
